/**
 * DAppCrypto
 * GitHub Website: https://dappcrypto.github.io/
 * GitHub: https://github.com/dappcrypto
 */

/**
 * MultiTokens v3 allows you to create tokens of different types
 * Read Contract: cAddr, getTaxL, getVersion, getNumberToken, getTokenAllData, getTokenInfo, cAList
 * Write Contract: deployToken
 * Write Contract, only token owner: deployToken, editTextData
 * Write Contract, only for owner: setAddr, setTaxL, setAList
 */

pragma solidity >=0.8.0;

import "./Ownable.sol";
import "./Wallet.sol";
import "./TaxCreationBlock.sol";

interface iDeployContract {
    function deploy(uint256[] memory nArr, address[] memory aArr, string[] memory sArr) external returns (address);
}

contract MultiTokens is Wallet, TaxCreationBlock {

    event NewContractTokenDeployed(address indexed newContractTokenAddress, uint256 indexed numberToken);

    uint256 public amountTokens = 0;
    uint256 public version=3;

    // mappingTokensContracts[aToken] = numberToken.
    mapping(address => uint256) public mappingTokensContracts;

    mapping(address => uint256) public mAList;

    address[] addrArr; // addrArr[aType]; // aType: 0 - SimpleToken, 1 - TaxToken, 2 - StableToken
    constructor () {}

    function cAddr() public view returns (address[] memory) {
        return addrArr;
    }
    
    function setAddr(address[] memory _addrArr) public onlyOwner {
       addrArr = _addrArr;
    }

    function cAList(address _address) public view returns (uint256) {
        return mAList[_address];
    }
    
    function setAList(address _address, uint256 _value) public onlyOwner {
       mAList[_address] = _value;
    }

    uint256[] maxsTaxL = [2000,2000,5,5]; // maxs Tax Sum in basis points [0->Sell,1->Buy] maxs Tax Acc [2->Sell,3->Buy]

    function setTaxL(uint256[] memory _maxsTaxL) public onlyOwner {
        require(_maxsTaxL.length == 4, "err");
        maxsTaxL = _maxsTaxL;
    }

    function getTaxL() public view returns (uint256[] memory) {
        return maxsTaxL;
    }

    struct TokenData {
        uint256 numberToken;
        uint256 typeToken;
        uint256 timeToken;
        address aToken;
        string sTextData;
    }
    // mappingTokensData[numberToken] = TokenData
    mapping(uint256 => TokenData) public mappingTokensData;

    function getVersion() public view returns (uint256) {
        return version;
    }

    function getNumberToken(address _aToken) public view returns (uint256) {
        return mappingTokensContracts[_aToken];
    }

    function getTokenAllData(uint256 _numberToken, address _addressAccount, address _addressSpender) public view returns (uint256[] memory, address[] memory, bool[] memory, string[] memory) {
        uint256[] memory uintArr = new uint256[](40);
        address[] memory addressArr = new address[](40);
        bool[] memory boolArr = new bool[](40);
        string[] memory stringArr = new string[](40);

        if(mappingTokensData[_numberToken].numberToken==0){
            return (uintArr, addressArr, boolArr, stringArr);
        }

        (uintArr, addressArr, stringArr) = getTokenInfo(mappingTokensData[_numberToken].aToken, _addressAccount, _addressSpender);

        // uintArr
        uintArr[10] = mappingTokensData[_numberToken].numberToken;
        uintArr[11] = mappingTokensData[_numberToken].timeToken;
        uintArr[12] = version;
        uintArr[13] = mappingTokensData[_numberToken].typeToken;

        // addressArr
        addressArr[10] = mappingTokensData[_numberToken].aToken;

        stringArr[10] = mappingTokensData[_numberToken].sTextData;

        return (uintArr, addressArr, boolArr, stringArr);
    }

    function getTokenInfo(address _addressToken, address _addressAccount, address addressSpender) public view returns (uint256[] memory, address[] memory, string[] memory) {
        uint256[] memory uintArr = new uint256[](40);
        address[] memory addressArr = new address[](40);
        string[] memory stringArr = new string[](40);

        // uintArr
        uintArr[0] = IERC20(_addressToken).decimals();
        uintArr[1] = IERC20(_addressToken).totalSupply();

        uintArr[2] = IERC20(_addressToken).balanceOf(_addressAccount);
        uintArr[3] = IERC20(_addressToken).allowance(_addressAccount, addressSpender);

        // addressArr
        addressArr[0] = IERC20(_addressToken).owner();

        // stringArr
        stringArr[0] = IERC20(_addressToken).name();
        stringArr[1] = IERC20(_addressToken).symbol();


        return (uintArr, addressArr, stringArr);
    }

    function getTokenAllDataByContract(address _aToken, address _addressOwner, address _addressSpender) public view returns (uint256[] memory, address[] memory, bool[] memory, string[] memory) {
        uint256 _numberToken = mappingTokensContracts[_aToken];
        return getTokenAllData(_numberToken, _addressOwner, _addressSpender);
    }

    function editTextData(uint256 _numberToken, string memory _sTextData) payable public {
        sendTaxCreation(address(0));
        require(IERC20(mappingTokensData[_numberToken].aToken).owner() == msg.sender, "only owner");
        mappingTokensData[_numberToken].sTextData = _sTextData;
    }

    function addTokenData(uint typeToken, address aToken, string memory _sTextData) internal {
        amountTokens++;

        mappingTokensContracts[aToken] = amountTokens;

        mappingTokensData[amountTokens].typeToken = typeToken;
        mappingTokensData[amountTokens].timeToken = block.timestamp;
        mappingTokensData[amountTokens].numberToken = amountTokens;
        mappingTokensData[amountTokens].aToken = aToken;
        mappingTokensData[amountTokens].sTextData = _sTextData;

        emit NewContractTokenDeployed(aToken, amountTokens);
    }

    // t_type: 0 - SimpleToken, 1 - TaxToken, 2 - StableToken
    function deployToken(
        uint256[] memory nArr,
        address[] memory aArr,
        string[] memory sArr
        ) payable public {

        sendTaxCreation(aArr[0]);
        uint256 t_type =  nArr[0];
        string memory _sTextData = sArr[0];
        address aParent = addrArr[t_type];

        if(t_type==2 || t_type==3){ // Tax limits
            require(
            nArr[3] <= maxsTaxL[0] && 
            nArr[4] <= maxsTaxL[1] && 
            nArr[5] <= maxsTaxL[2] && 
            nArr[6] <= maxsTaxL[3]
            , "err");
        }

        address aToken = iDeployContract(aParent).deploy(nArr, aArr, sArr);

        addTokenData(t_type, aToken, _sTextData);
    }


}"
