 /**
 * TaxCreationBlock - contract for managing taxes and partners
 */

pragma solidity >=0.8.0;

import "./Ownable.sol";

contract TaxCreationBlock is Ownable {
    uint256 public taxCreation = 10000000000000000; // 0.01
    address public taxCreationA = address(this);

    // invite
    uint256 public IProfSum = 0; // inviters profit
    uint256 public invBPDisc = 2000; // discount 20%
    uint256 public invBP = 3000; // inviter profit 30%
    mapping(address => uint256) public mInvProf; // inviter -> profit ETH

    function getTaxCData(address inviter) external view returns (address, uint256, uint256, uint256, uint256, uint256) {
        return (taxCreationA, taxCreation, invBPDisc, invBP, mInvProf[inviter], IProfSum);
    }

    function setTaxCData(address _addressTax, uint256 _amountTax, uint256 _invBPDisc, uint256 _invBP) public onlyOwner {
        if(_addressTax==address(0)){ _addressTax = address(this); }
        taxCreationA = _addressTax;
        taxCreation = _amountTax;
        invBPDisc = _invBPDisc;
        invBP = _invBP;
    }

    function sendTaxCreation(address inviter) payable public {
        uint256 discount = 0;
        uint256 InvProf = 0;
        if(inviter != address(0) && inviter != msg.sender){
            discount = taxCreation * invBPDisc / 10000;
            InvProf = taxCreation * invBP / 10000;
            payable(inviter).transfer(InvProf);
            mInvProf[inviter] = mInvProf[inviter] + InvProf;
            IProfSum = IProfSum + InvProf;
        }
        uint256 taxCreat = taxCreation - discount;
        require(msg.value >= taxCreat, "taxCreation error");
        if(taxCreationA!=address(this)){
            payable(taxCreationA).transfer(taxCreat);
        }
        return;
    }
}"
